-- 361 · Catálogo base de obra civil.
--
-- Lista general (sin precios ni proveedores) para elegir el material en /procura por
-- categoría: cabillas, arena y piedra, bloques, tuberías, clavos y tornillería,
-- sanitarios, puertas y ventanas, techos, herramientas, servicios, etc.
--
-- No reemplaza al catálogo de cada empresa (global_inventory): al elegir un ítem, el bot
-- busca o crea el material de la empresa de la obra y lo enlaza aquí (catalogo_base_id).
-- Así el catálogo real se llena solo y ordenado. El texto libre sigue disponible.

create table if not exists public.ci_catalogo_base (
  id uuid primary key default gen_random_uuid(),
  codigo text not null unique,
  categoria text not null,
  categoria_orden integer not null default 0,
  grupo text not null default 'Materiales',
  nombre text not null,
  unidad text not null default 'UND',
  palabras_clave text,
  orden integer not null default 0,
  activo boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.ci_catalogo_base is
  'Catálogo base de obra civil para /procura (categoría → ítem). Sin precios. Migración 361.';

create index if not exists idx_ci_catalogo_base_categoria
  on public.ci_catalogo_base (categoria_orden, orden) where activo;

alter table public.ci_catalogo_base enable row level security;

drop policy if exists ci_catalogo_base_lectura on public.ci_catalogo_base;
create policy ci_catalogo_base_lectura on public.ci_catalogo_base
  for select to authenticated using (true);

revoke all on public.ci_catalogo_base from anon;
grant select on public.ci_catalogo_base to authenticated;
grant all on public.ci_catalogo_base to service_role;

alter table public.global_inventory
  add column if not exists catalogo_base_id uuid references public.ci_catalogo_base (id) on delete set null;

create index if not exists idx_global_inventory_catalogo_base
  on public.global_inventory (catalogo_base_id, entidad_id) where catalogo_base_id is not null;


on conflict (codigo) do update set
  categoria = excluded.categoria,
  categoria_orden = excluded.categoria_orden,
  grupo = excluded.grupo,
  nombre = excluded.nombre,
  unidad = excluded.unidad,
  palabras_clave = excluded.palabras_clave,
  orden = excluded.orden,
  updated_at = now();
